from datetime import datetime, timezone

from sqlalchemy import Integer, Text, DateTime, ForeignKey
from sqlalchemy.orm import Mapped, mapped_column

from app.core.database import Base


class PaperAnalysis(Base):
    __tablename__ = "paper_analyses"

    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    paper_id: Mapped[int] = mapped_column(
        Integer, ForeignKey("papers.id", ondelete="CASCADE"), nullable=False, unique=True
    )

    # Structured analysis generated by LLM
    abstract: Mapped[str] = mapped_column(Text, nullable=True)
    innovation: Mapped[str] = mapped_column(Text, nullable=True)
    methods: Mapped[str] = mapped_column(Text, nullable=True)
    experiments: Mapped[str] = mapped_column(Text, nullable=True)
    limitations: Mapped[str] = mapped_column(Text, nullable=True)
    related_work: Mapped[str] = mapped_column(Text, nullable=True)
    one_sentence: Mapped[str] = mapped_column(Text, nullable=True)
    pros_cons: Mapped[str] = mapped_column(Text, nullable=True)

    created_at: Mapped[datetime] = mapped_column(
        DateTime, default=lambda: datetime.now(timezone.utc)
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime,
        default=lambda: datetime.now(timezone.utc),
        onupdate=lambda: datetime.now(timezone.utc),
    )
